//Groovy script to retrieve values from XML and put them on headers
//Only to be used in combination with WHLSL_20
//Version 1.00 - 18.02.2021
//Version 2.00 - 23.02.2021 - opties GET, SAVE en LOAD ingebouwd.
//Version 2.01 - 16.03.2021 - listHeaders in header opslaan bij elke SAVE, dus na elke Group, en niet alleen indien headers gevonden (anders gaat ExistingHeaderList verloren). 
//Version 2.02 - 17.05.2021 - acties toegevoegd op xPath: count, exists, gt.
//Version 2.03 - 21.05.2021 - actie eval toegevoegd.
//Version 2.04 - 25.05.2021 - SAVE alle headers van steps in 1x 
//Version 2.05 - 07.06.2021 - Float op lege response goed afvangen (GET / SAVE), //RESTmessages voor /rmessage
//Version 2.06 - 18.06.2021 - Function simpleReplace om headers in ddg_headers te vervangen met waarden.
//Version 2.07 - 12.07.2021 - actie xpath toegevoegd, waarbij //../ vervangen wordt door het basepath (//*[substring(name(),1,21) = "RESTmessage_Response_"]/*[@messageId=""])
//Version 2.08 - 15.07.2021 - headers met attribuut @permanent=true worden behouden in ${listHeaders} en opnieuw op header gezet bij actionHeaderList=CLEAR
//Version 2.09 - 27.07.2021 - escapeXml bij SAVE (opslaan op listHeaders) en LOAD (lezen vanuit listHeaders)
//Version 3.00 - 29.07.2021 - Xpath 2.0 libraries
//Version 3.01 - 11.08.2021 - /*[@messageId="'+"${messageId}"+'"]/' bij GET en SAVE in de action=xpath toegevoegd.
//Version 3.02 - 25.10.2021 - try{catch{ ingebouwd rondom switch om uitzonderingen in actions=xpath / eval netjes af te vangen.
//Version 3.03 - 24.11.2021 - headerName vermelden bij try/catch om zoeken naar fout te vereenvoudigen.
//Version 3.04 - 17.01.2022 - bij LOAD de unescapeXml functie gebruiken om de headers weer mee te vullen.
//Version 3.05 - 01.02.2022 - bij GET de header add_to_listHeaders gebruiken om listHeaders niet of wel (bij wrapUp) aan te vullen.
//Version 4.00 - 03.03.2022 - Aangepast op WHLSL_20bc_v2 die zichzelf niet meer aanroept, maar via extra split werkt. xpath 1.0 functies bij GET verwijderd. 
//								SAVE optie in zijn geheel niet meer nodig, omdat listHeaders na elke GET nu aangevuld wordt. Die is dan ook verwijderd in deze versie.
//Version 4.01 - 10.12.2022 - Aanpassingen in GET, LOAD en CLEAR om Dovetail headers met unescaped karakter te laden (bv A&B) maar de listHeaders t.b.v. de "XML" Globale variabele met unescaped XML karakters (bv A&amp;B)
//								Dit is noodzakelijk omdat in dit script xpath gebruikt wordt om vanuit de globale variabel waarden terug te zetten naar de Dovetail headers.
//								De aanpassing van 17.01.2022 bleek niet in alle gevallen correct. De beoogde werking (listheaders escaped, Dovetail headers unescaped) is nu voor GET, LOAD en CLEAR doorgevoerd.
//Version 4.02 - 11.12.2022 - Dubbele headers/headernamen in listHeaders verwijderen (ingebouwd bij GET, als daar duplicaten als wegzijn richting globale variabele, zal LOAD geen duplicaten kunnen bevatten).
//Version 4.03 - 12.12.2022 - catch valide XML zette de exceptions_20d header niet op 'true' maar op 'e'.
//Version 4.04 - 27.03.2023 - Maximum aantal terug te zetten headers van 25 naar 50.
//Version 4.05 - 21.01.2025 - Compatible gemaakt met 4.17 
//Version 4.06 - 10.02.2025 - script aangepast om van eval's/xpath's hier al de headerwaarden hier op te nemen. Hiermee kan de simpleReplace in de 20bc vervallen en wordt voorkomen - bij gebruik van dezelfde (ddg_)header in ddg_headers - dat alle waarden met de laatst berekende waarde vervangen worden. Wat een onjuist beeld geeft in de integrationLog.
//Version 4.07 - 11.02.2025 - actie "replace" toegevoegd (naast eval en xpath) om het ook eenvoudig mogelijk te maken in headers in strings te vervangen (simpleReplace) en daarvan geen groovy scriptje van te hoeven schrijven (om eval te kunnen gebruiken).

//-------------------------------------------------------------------------------------------------------
//Onderstaande headers zijn te gebruiken voor testen (dan uiteraard wel de "REM" weghalen/terugzetten)
//t.b.v. LOAD
//request.setHeader("existingHeaderList",'<header name="var_1_int">123</header><header name="var_2_str">20D&amp;TEST&lt;123&gt;</header><header name="var_3_int_permanent" permanent="true">456</header><header name="var_4_str_permanent" permanent="true">20D&amp;TEST&lt;456&gt;</header>')
//t.b.v. GET
//request.setHeader("existingHeaderList",'<header name="var_1_int">123</header><header name="var_1_int">456</header><header name="var_1_int">789</header>')
//overige sturingsinformatie voor 20d
//request.setHeader("actionHeaderList","LOAD")
//request.setHeader("clearHeaderList","false")
//request.setHeader("stepId","0")
//request.setHeader("sequence","0")

//escapen van speciale XML karakters, bij opslaan van waarden in listheaders globale variabele (SAVE)
//dit is feitelijk een XML waaruit de waarden XML compliant moeten zijn omdat die in 20c via simpleReplace ook weer op plaats ${header} worden gezet in de XML.
//-------------------------------------------------------------------------------------------------------
def escapeXml(str)
{
	str=str.replace("&","&amp;")
	str=str.replace(">","&gt;")
	str=str.replace("<","&lt;")
	str=str.replace("'","&apos;")
	str=str.replace('"','&quot;')
	return str
}

//unescapen van speciale XML characters, voor LOAD vanuit globale variabele (waar ze bij SAVE escaped zijn).
def unescapeXml(str)
{
	str=str.replace("&amp;","&")
	str=str.replace("&gt;",">")
	str=str.replace("&lt;","<")
	str=str.replace("&apos;","'")
	str=str.replace('&quot;','"')
	return str
}


//Bepalen van headers in string (dovetail syntax + naam) en vervangen met hun waarde
//-------------------------------------------------------------------------------------------------------
def simpleReplace(line) 
{
	def header_found = true
	while (("${header_found}" == "true"))
	{
		//zoek eerste header in string (dovetail syntax)
		def header_dovetail = line.find('(\\$\\{.*?\\})')

		if ("${header_dovetail}" != "null")
		{
			//bepaal de naam van de header
			def header_name = header_dovetail.find('[^.]+(?=})')

			//haal de waarde van de header op
			def header_value = request.getHeader("${header_name}")

			//vervang de header in de line
			line = line.replace("${header_dovetail }","${header_value}")

		}
		else
		header_found = "false"
	}
	return line
}
//-------------------------------------------------------------------------------------------------------
//Import libraries
import groovy.xml.*;
import org.w3c.dom.Node;
import org.w3c.dom.Document;
import javax.xml.parsers.DocumentBuilderFactory;
import net.sf.saxon.xpath.XPathEvaluator;

// Variabels specific for this integration
// StepId = Id huidige step
// stepSequence=teller om headers binnen messages van deze step op te halen.
// actionHeaderList = GET (responses op headers zetten tussen steps), SAVE (toevoegen aan globale variabele na RESTgroup) LOAD (van globaal naar headers zetten op step=0).
stepId = request.getHeader('stepId')
stepSequence = request.getHeader('sequence')
actionHeaderList = request.getHeader('actionHeaderList')
if ("${actionHeaderList}" == 'null')
{ actionHeaderList = "GET" }

//setting op RESTmessages niveau, globale variabele met headerwaarden wissen voor volgende RESTmessages of niet
//alleen in combinatie met actionHeaderList = LOAD, default = leeg maken.
clearHeaderList = request.getHeader('clearHeaderList')
if ("${clearHeaderList}" == 'null')
{ clearHeaderList = 'true' }
if (("${clearHeaderList}" == 'true') && ("${actionHeaderList}" == 'LOAD'))
{ 
	request.setHeader("actionHeaderList","CLEAR")
	actionHeaderList="CLEAR"
}

// General variables for processing XML
def xmlValid="true"
def xmlString = request.getBody(String.class)
request.setHeader ("exceptions_20d","false")

try{
	def xmlRecords = new XmlSlurper().parseText(xmlString);      
} catch(Exception e){
xmlValid="false"
xmlString="<invalid_whls20_xml/>"
request.setHeader ("exceptions_20d","true")
request.setHeader ("exceptionText_20d","XML-structure not valid.")}

//parse XML om de ddg_header formules te vervangen met de headerwaarden die daarin gebruikt zijn (ipv via SimpleReplace in de 20bc)
bodyInXml = new XmlParser().parseText(xmlString)

//-----------------------
// get responsevalues from XML en put on headers
// headerSequence = teller om alle in de mapping gedefinieerde headers binnen één message op te halen.
// xpath_messageId = xpath naar uniek Id voor de call (en daarmee response) in rmessage
// xpath_headerName = xpath naar de naam van de header zoals gedefinieerd in de mapping voor WHLSL_20, waar de responsewaarde op moet komen.
// xpath_pathToValue = xpath naar het pad wat gebruikt moet worden om de waarde uit de response te halen

def checkNextHeader = true
Integer headerSequence = 1
def xpath_pathToValue = ""
def pathToValue = ""

//lijst van headerwaarden die opgeslagen zijn in de globale variabele voor de betreffende integratie(run).
//wordt gebruikt om bestaande lijst aan te vullen (via SAVE binnen steps, of via LOAD voorafgaand aan volgende RESTmessages
//in het geval van LOAD de inhoud van de globale variabele voorafgaand aan het script op de header 'existingHeaderList' zetten.

existingHeaderList = request.getHeader('existingHeaderList')
if ("${existingHeaderList}" == '<placeholder/>'){existingHeaderList = "" }
listHeaders = "${existingHeaderList}"


//Afhandelen acties GET, LOAD, SAVE of CLEAR
//------------------------------------------
if ("${xmlValid}" == "true")
{
request.setHeader ("exceptions_20d","false")

Document doc = DocumentBuilderFactory.newInstance()
                    .newDocumentBuilder()
                    .parse(new org.xml.sax.InputSource(new java.io.StringReader(xmlString)))
xmlRecords = doc.getDocumentElement()
// Create XPathFactory and use it to execute our XPath on our XML
xpath = new XPathEvaluator();

try{
switch ("${actionHeaderList}")
{
case "GET" : 
//Vullen headers vanuit response (Dovetail headers worden gevuld met waarden vanuit API response) en eventueel aanvullen listHeaders
//Dovetail headers bevatten de unescaped XML karakters
//De opgebouwed listheaders (die opgeslagen wordt in de globale werkvariabele) bevat de escaped XML karakters (omdat die via LOAD/CLEAR met xpath weer teruggehaald worden).
//De API responses, in de regel JSON, worden via JSONtoXML omgezet naar XML en de response zou daarmee de escaped karakters moeten bevatten
//Die worden via de xpath weer unescaped, dus bij terugzetten op listHeaders vervolgens weer escapen.

def xpath_messageId = '//rmessage[@step="'+"${stepId}"+'"]['+"${stepSequence}"+']/@messageId'	
messageId=xpath.evaluate("${xpath_messageId}", xmlRecords)

//mogelijkheid om headers ook bij GET aan listHeaders toe te voegen (nodig bij nieuwe opzet WHLSL20bc zonder loop, en bij wrapUp=true)
add_to_listHeaders = request.getHeader('add_to_listHeaders')
if ("${add_to_listHeaders}" == 'null')
{ add_to_listHeaders = "false" }

//Bepalen van waarden bij ddg_headers, met een maximum van 50 per Step (totaal aantal ddg_headers binnen 1 StepGroup)
while (("${checkNextHeader}" == "true") && (Integer.parseInt("${headerSequence}") <= Integer.parseInt("50")))
{
	xpath_pathToValue = '//rmessage[@step="'+"${stepId}"+'"]['+"${stepSequence}"+']/ddg_headers/xpath['+"${headerSequence}"+']/text()'
	pathToValue=simpleReplace(xpath.evaluate("${xpath_pathToValue}", xmlRecords))

	if ("${pathToValue}"!="")
	{
	xpath_headerName =  '//rmessage[@step="'+"${stepId}"+'"]['+"${stepSequence}"+']/ddg_headers/xpath['+"${headerSequence}"+']/@name'	
	xpath_headerAction =  '//rmessage[@step="'+"${stepId}"+'"]['+"${stepSequence}"+']/ddg_headers/xpath['+"${headerSequence}"+']/@action'
	xpath_headerType =  '//rmessage[@step="'+"${stepId}"+'"]['+"${stepSequence}"+']/ddg_headers/xpath['+"${headerSequence}"+']/@type'
	xpath_headerPermanent =  '(//rmessage/ddg_headers/xpath)['+"${headerSequence}"+']/@permanent'

	headerName=xpath.evaluate("${xpath_headerName}", xmlRecords)	
	headerAction=xpath.evaluate("${xpath_headerAction}", xmlRecords)			
	headerType=xpath.evaluate("${xpath_headerType}", xmlRecords)
	headerPermanent=xpath.evaluate("${xpath_headerPermanent}", xmlRecords)	

	if ("${headerType}"=="null") { headerType="String" } 	
	switch ("${headerAction}")
	{ 
		case "eval" : request.setHeader("${headerName}",evaluate("${pathToValue}"))
		switch ("${headerType}")
		{ 
			case "Float" : fullpath_Value = evaluate("${pathToValue}")
			if ("${fullpath_Value}"=="") { fullpath_Value="0" }
			else
			{ fullpath_Value=fullpath_Value.toFloat().round(4)}	
			break;
			default: fullpath_Value = evaluate("${pathToValue}")
			break;
		}			
		break;		

		case "xpath" : xpath_basepath = '//*[substring(name(),1,9) = "rmessage_"][@messageId="'+"${messageId}"+'"]/'		
		xpath_fullpath = pathToValue.replace('//../',"${xpath_basepath}")
		fullpath_Value = xpath.evaluate("${xpath_fullpath}", xmlRecords)
		request.setHeader("${headerName}", fullpath_Value)
		break;

		case "replace" : 
		fullpath_Value = pathToValue
		request.setHeader("${headerName}", pathToValue)
		break;

		default: xpath_fullpath='//*[substring(name(),1,9) = "rmessage_"][@messageId="'+"${messageId}"+'"]'+"${pathToValue}"
		fullpath_Value = xpath.evaluate("${xpath_fullpath}", xmlRecords)		
		request.setHeader("${headerName}", fullpath_Value)
		break;

	}

	//Het resultaat van het xpath/eval opnemen in @result, geevalueerde expressie aanpassen met gebruikte headerwaarden.
	foundNode = bodyInXml.'**'.rmessage[0].ddg_headers.xpath[headerSequence-1]
	if (foundNode != null)
	{	
		if (headerAction != "replace") {foundNode.value = "${pathToValue}"}
		foundNode.attributes()['result']= fullpath_Value
	}

	headerSequence++

	if ("${add_to_listHeaders}"=="true")
	{
	//verwijderen eventuele duplicate headers om vervuiling in listHeaders te voorkomen
	regex = /<header name="$headerName"([\S\s]*?)(?:header>)/
	listHeaders  = listHeaders.replaceFirst(regex , "")	
		if ("${headerPermanent}"=="true")	
		{
			listHeaders = listHeaders + '<header name="'+"${headerName}"+'" permanent="true">'+escapeXml("${fullpath_Value}")+'</header>'
		} else
		{
			listHeaders = listHeaders + '<header name="'+"${headerName}"+'">'+escapeXml("${fullpath_Value}")+'</header>'
		}
	}

	//zet headerwaarden op Groovy variabelen om ook evalutate/Eval.Me("formule met headers vanuit mapping") te kunnen gebruiken.	
	//dit wijzigt dus niet de waarde op de headers, alleen op de Groovy variabele om bij gebruik in volgende ddg_header te kunnen gebruiken bij berekeningen.
	switch ("${headerType}")
	{ 
		case "Float" : headerValue=request.getHeader("${headerName}")
		if ("${headerValue}"!="") {headerValue=headerValue.toFloat().round(4)}
		else
		{ headerValue = 0 }
		break;
		default: headerValue=request.getHeader("${headerName}")
		break;
	}
	evaluate("${headerName} = headerValue")	

	} else checkNextHeader=false
}

if ("${add_to_listHeaders}"=="true")
{
	request.setHeader('listHeaders', "${listHeaders}".toString())
}
break;

case "LOAD":
// Dovetail headers na een split opnieuw vullen vanuit Globale variabele
// Dit wordt gedaan met xpath, dus escaped XML uit globale variabele terug naar unescaped in Dovetail header
// De listHeaders t.b.v. opslag in de globale variabel tussen splits wordt niet aangepast.
list='<Headers>'+"${listHeaders}"+'</Headers>'
request.setBody(list)

	Document doc_LH = DocumentBuilderFactory.newInstance()
                    .newDocumentBuilder()
                    .parse(new org.xml.sax.InputSource(new java.io.StringReader(request.getBody(String.class))))
	xmlRecords_LH = doc_LH.getDocumentElement()


// Create XPathFactory and use it to execute our XPath on our XML
def xpath_LH = new XPathEvaluator();

while (("${checkNextHeader}" == "true") && (Integer.parseInt("${headerSequence}") <= Integer.parseInt("100")))
{
	def xpath_listheaderName = '//header['+"${headerSequence}"+']/@name'
	def xpath_ToValue = '//header['+"${headerSequence}"+']/text()'
	def headerName = xpath_LH.evaluate("${xpath_listheaderName}", xmlRecords_LH)
	if ("${headerName}"!="")
	{
	request.setHeader("${headerName}", xpath_LH.evaluate("${xpath_ToValue}", xmlRecords_LH)) 
	headerSequence++
	} else checkNextHeader=false
}
break;

case "CLEAR": 
// Dovetail headers na een split opnieuw vullen vanuit Globale variabele
// Hierbij alleen de headers terugzetten met permanent = true
// Dit wordt gedaan met xpath, dus escaped XML uit globale variabele terug naar unescaped in Dovetail header
// De listHeaders t.b.v. opslag in de globale variabele wordt ook aangepast (ontdaan van alle headers die niet permanent zijn).
	list='<Headers>'+"${listHeaders}"+'</Headers>'
	request.setBody(list)
	//def xmlRecords_P = new XmlSlurper().parseText(request.getBody(String.class));

	Document doc_P = DocumentBuilderFactory.newInstance()
                    .newDocumentBuilder()
                    .parse(new org.xml.sax.InputSource(new java.io.StringReader(request.getBody(String.class))))
	xmlRecords_P = doc_P.getDocumentElement()	


	// Create XPathFactory and use it to execute our XPath on our XML
	def xpath_P = new XPathEvaluator();	

	//	Controleer of er headers permanent zijn
	def countPermanent = xpath_P.evaluate("count(//header[@permanent='true'])", xmlRecords_P);
	def permanent_listHeaders = ""

	if (Integer.parseInt("${countPermanent}") != Integer.parseInt("0"))
	{
		//doorloop alle headers en verwijder alleen headers die niet permanent zijn.
		while (("${checkNextHeader}" == "true") && (Integer.parseInt("${headerSequence}") <= Integer.parseInt("100")))
		{
			def xpath_listheaderName = '//header[@permanent="true"]['+"${headerSequence}"+']/@name'
			def xpath_ToValue = '//header[@permanent="true"]['+"${headerSequence}"+']/text()'
			def headerName = xpath_P.evaluate("${xpath_listheaderName}", xmlRecords_P)
			def headerValue = xpath_P.evaluate("${xpath_ToValue}", xmlRecords_P)

			if ("${headerName}"!="")
			{
			request.setHeader("${headerName}",headerValue)
			permanent_listHeaders = permanent_listHeaders + '<header name="'+"${headerName}"+'" permanent="true">'+escapeXml("${headerValue}")+'</header>'

			headerSequence++
			} else checkNextHeader=false
		}		
		request.setHeader('listHeaders', "${permanent_listHeaders}".toString())
	} else	
	{
		request.setHeader('listHeaders', '<placeholder/>')
	}
	break;
}
} catch(Exception e){
request.setHeader ("exceptions_20d","true")
RESTgroupId=request.getHeader("RESTgroupId")
request.setHeader ("exceptionText_20d","Message: "+" (${headerName}) "+"- ${e}"+" ,GSID: "+"${RESTgroupId}"+"-"+"${messageId}"+"-"+"${stepId}")}
}

def headersFound = false
if (Integer.parseInt("${headerSequence}") > Integer.parseInt("1"))
{ 
	headersFound = true
}

request.setHeader("headersFound","${headersFound}".toString())

//return xmlString
//return bodyInXml, hierbij zijn parameters/headerwaarden vervangen met de waarden zoals ze op moment van xpath/eval waren.
return XmlUtil.serialize(bodyInXml).replaceAll(/<\?xml.*?\?>/,"")
